// The link key k: what it is, how it is read out of a link, and that it cannot
// leak by being stringified. keyRows comes from keycheck-vectors.json, the file the
// Go suite reads too, generated by an independent script and never by either
// implementation.
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { inspect } from 'node:util';
import { describe, expect, it } from 'vitest';
import {
    LINK_KEY_RE,
    LinkKey,
    base64UrlDecode,
    base64UrlEncode,
    linkKeyBytes,
    linkKeyText,
    makeLinkKey,
    parseLinkKey,
    readShareFragment,
    sameLinkKey,
    shareLinkChanged,
} from './linkKey';
import { getRoomFromUrl } from './roomLink';

const VECTORS = JSON.parse(
    readFileSync(new URL('../../cli/engine/transfer/testdata/keycheck-vectors.json', import.meta.url), 'utf8')
) as { keyRows: Array<{ name: string; text: string; valid: boolean }> };

const ROOM = '6f207790-92a6-4662-bb68-4c4059f75139';
const OTHER_ROOM = '227103fc-95ba-40af-a35b-2f7c9526d601';
const K = 'AAECAwQFBgcICQoLDA0ODw'; // 16 bytes 0..15, a canonical key ending in w
const K2 = 'AQIDBAUGBwgJCgsMDQ4PEA'; // 16 bytes 1..16

describe('keyRows of the shared vector file', () => {
    it('holds rows on both sides of the rule, so the loop below is not vacuous', () => {
        expect(VECTORS.keyRows.filter((r) => r.valid).length).toBeGreaterThan(2);
        expect(VECTORS.keyRows.filter((r) => !r.valid).length).toBeGreaterThan(2);
    });

    for (const row of VECTORS.keyRows) {
        it(`${row.name}: ${row.valid ? 'parses' : 'refused'}`, () => {
            const key = parseLinkKey(row.text);
            expect(key !== null).toBe(row.valid);
            if (key) expect(linkKeyText(key)).toBe(row.text);
        });
    }
});

describe('parseLinkKey', () => {
    it('reads the value only when it is a canonical string', () => {
        for (const bad of [undefined, null, 16, true, {}, [K], { toString: () => K }, new String(K)]) {
            expect(parseLinkKey(bad), String(typeof bad)).toBeNull();
        }
    });

    it('refuses a trailing newline, which a looser regex anchor would let through', () => {
        expect(parseLinkKey(K + '\n')).toBeNull();
        expect(parseLinkKey('\n' + K)).toBeNull();
        expect(parseLinkKey(K + '\r\n')).toBeNull();
        expect(LINK_KEY_RE.test(K + '\n')).toBe(false);
    });

    it('takes every last character the two padding bits allow and no other', () => {
        const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
        const stem = K.slice(0, 21);
        const accepted = [...alphabet].filter((c) => parseLinkKey(stem + c) !== null);
        expect(accepted).toEqual(['A', 'Q', 'g', 'w']);
    });

    it('decodes to the 16 bytes the text names', () => {
        const key = parseLinkKey(K) as LinkKey;
        expect([...linkKeyBytes(key)]).toEqual(Array.from({ length: 16 }, (_, i) => i));
        expect([...linkKeyBytes(parseLinkKey('_____________________w') as LinkKey)]).toEqual(new Array(16).fill(0xff));
    });

    it('hands out a copy of the bytes, so no caller can change the key', () => {
        const key = parseLinkKey(K) as LinkKey;
        linkKeyBytes(key).fill(0);
        expect([...linkKeyBytes(key)].slice(0, 3)).toEqual([0, 1, 2]);
    });
});

describe('makeLinkKey', () => {
    it('fills exactly 16 bytes and gives a canonical key that round-trips', () => {
        const seen: number[] = [];
        const key = makeLinkKey((b) => {
            seen.push(b.length);
            b.set(Uint8Array.from({ length: 16 }, (_, i) => 0xf0 + i));
            return b;
        });
        expect(seen).toEqual([16]);
        const text = linkKeyText(key);
        expect(LINK_KEY_RE.test(text)).toBe(true);
        expect(linkKeyText(parseLinkKey(text) as LinkKey)).toBe(text);
    });

    it('uses the browser CSPRNG by default, called on crypto (a bare reference throws Illegal invocation)', () => {
        const a = linkKeyText(makeLinkKey());
        const b = linkKeyText(makeLinkKey());
        expect(LINK_KEY_RE.test(a)).toBe(true);
        expect(a).not.toBe(b);
    });

    it('stays canonical over many random keys', () => {
        for (let i = 0; i < 500; i++) expect(LINK_KEY_RE.test(linkKeyText(makeLinkKey()))).toBe(true);
    });

    it('refuses a key of any other size', () => {
        expect(() => new LinkKey(new Uint8Array(15))).toThrow();
        expect(() => new LinkKey(new Uint8Array(17))).toThrow();
    });

    it('copies what it is given, so a later write to the source cannot change the key', () => {
        const source = new Uint8Array(16).fill(7);
        const key = new LinkKey(source);
        const before = linkKeyText(key);
        source.fill(9);
        expect(linkKeyText(key)).toBe(before);
        // The bytes too, which are what the tag is keyed with. The text above is
        // computed once, so it alone would pass with no copy at all.
        expect([...linkKeyBytes(key)]).toEqual(new Array(16).fill(7));
    });
});

describe('a link key cannot leak by being stringified', () => {
    const key = parseLinkKey(K) as LinkKey;

    it('toString and toJSON say what it is and nothing else', () => {
        expect(key.toString()).toBe('[link key]');
        expect(key.toJSON()).toBe('[link key]');
        expect(String(key)).toBe('[link key]');
        expect(`${key}`).toBe('[link key]');
        expect(key + '').toBe('[link key]');
    });

    it('JSON.stringify writes the placeholder wherever the key sits, which is what Sentry normalize calls', () => {
        expect(JSON.stringify(key)).toBe('"[link key]"');
        expect(JSON.stringify({ a: { b: [key] } })).toBe('{"a":{"b":["[link key]"]}}');
    });

    it('holds nothing an object walk can find', () => {
        expect(Object.keys(key)).toEqual([]);
        expect(Object.getOwnPropertyNames(key)).toEqual([]);
        expect(Object.getOwnPropertySymbols(key)).toEqual([]);
        expect({ ...key }).toEqual({});
        expect(structuredClone(key)).toEqual({});
    });

    it('util.inspect, what a console.log prints in Node, shows no key material', () => {
        const printed = inspect(key, { depth: 5, showHidden: true });
        expect(printed).not.toContain(K);
        expect(inspect({ key }, { depth: 5 })).not.toContain(K);
    });

    it('linkKeyText and linkKeyBytes refuse anything that is not a LinkKey, with fixed words', () => {
        const fake = { toString: () => K } as unknown as LinkKey;
        expect(() => linkKeyText(fake)).toThrow('not a link key');
        expect(() => linkKeyBytes(fake)).toThrow('not a link key');
    });
});

describe('the routes back to key material', () => {
    /** Every source file of the app, with comments left in: a mention counts. */
    function appSources(dir: URL, found: Array<{ path: string; text: string }> = []) {
        for (const entry of readdirSync(dir, { withFileTypes: true })) {
            const child = new URL(`${entry.name}${entry.isDirectory() ? '/' : ''}`, dir);
            if (entry.isDirectory()) appSources(child, found);
            else if (/\.tsx?$/.test(entry.name) && !/\.test\.tsx?$/.test(entry.name)) {
                found.push({ path: fileURLToPath(child), text: readFileSync(child, 'utf8') });
            }
        }
        return found;
    }

    const root = new URL('../', import.meta.url);
    const sources = ['lib/', 'components/', 'hooks/', 'app/'].flatMap((d) => appSources(new URL(d, root)));
    const rel = (p: string) => p.slice(fileURLToPath(root).length).replace(/\\/g, '/');
    const callers = (name: string) => sources.filter((s) => s.text.includes(`${name}(`)).map((s) => rel(s.path)).sort();

    it('reads the app, so the two checks below are not vacuous', () => {
        expect(sources.length).toBeGreaterThan(100);
        expect(callers('getRoomFromUrl').length).toBeGreaterThan(0);
    });

    it('linkKeyText is called by the code that builds a share link, and nothing else', () => {
        for (const caller of callers('linkKeyText')) expect(['lib/linkKey.ts', 'lib/roomLink.ts']).toContain(caller);
    });

    it('linkKeyBytes is called by the HMAC, and nothing else', () => {
        for (const caller of callers('linkKeyBytes')) expect(['lib/linkKey.ts', 'lib/transfer/keyCheck.ts']).toContain(caller);
    });
});

describe('base64url', () => {
    it('agrees with Node for every length that ends a group differently', () => {
        for (let length = 0; length < 70; length++) {
            const bytes = Uint8Array.from({ length }, (_, i) => (i * 37 + 11) & 0xff);
            const text = base64UrlEncode(bytes);
            expect(text).toBe(Buffer.from(bytes).toString('base64url'));
            expect([...base64UrlDecode(text, length)]).toEqual([...bytes]);
        }
    });
});

describe('readShareFragment, a link with no key: exactly what getRoomFromUrl says', () => {
    const rows: Array<[string, string, string]> = [
        ['no fragment, no query (the sender page)', '', ''],
        ['a bare hash', '#', ''],
        ['today\'s fragment', `#room=${ROOM}`, ''],
        ['today\'s fragment with the nonce query', `#room=${ROOM}`, '?s=abc'],
        ['the legacy query link', '', `?room=${ROOM}`],
        ['a fragment beats the query', `#room=${ROOM}`, `?room=${OTHER_ROOM}`],
        ['a duplicate room, first wins as URLSearchParams.get does', `#room=${ROOM}&room=${OTHER_ROOM}`, ''],
        ['an unknown parameter', `#room=${ROOM}&x=1`, ''],
        ['a request-link-shaped fragment', `#${ROOM}`, ''],
        ['upper case keeps its case', `#room=${ROOM.toUpperCase()}`, ''],
    ];
    for (const [name, hash, search] of rows) {
        it(name, () => {
            const got = readShareFragment(hash, search);
            expect(got.room).toBe(getRoomFromUrl(hash, search));
            expect(got.key).toBeNull();
            expect(got.incomplete).toBe(false);
        });
    }

    // B14. The room field stays today's answer, and the fragment that carries a
    // room with nothing valid in it says so, so a page never reads a cut link as
    // "no room, so this is the sender".
    it('a fragment that carries room and no valid room is incomplete, with today\'s room beside it', () => {
        for (const [hash, search, room] of [
            ['#room=', '', null],
            ['#room', '', null],
            ['#room=not-a-uuid', '', 'not-a-uuid'],
            [`#room=${ROOM}x`, '', `${ROOM}x`],
        ] as Array<[string, string, string | null]>) {
            expect(readShareFragment(hash, search), hash).toEqual({ room, key: null, incomplete: true });
            expect(room).toBe(getRoomFromUrl(hash, search));
        }
    });

    // A web link cut before its fragment: the sending page must not open from it.
    it('a share link\'s nonce with nothing behind it is incomplete', () => {
        const cut = { room: null, key: null, incomplete: true };
        expect(readShareFragment('', '?s=abc')).toEqual(cut);
        expect(readShareFragment('#', '?s=abc')).toEqual(cut);
    });

    // An in-page anchor on a page already holding a link asks for nothing, and the tab
    // keeps its transfer (shareLinkChanged).
    it('a nonce and a fragment that names no link is no damaged link', () => {
        expect(readShareFragment('#faq', '?s=abc')).toEqual({ room: null, key: null, incomplete: false });
    });

    it('an empty fragment room falls back to a valid query room, as today, and is not incomplete', () => {
        expect(readShareFragment('#room=', `?room=${ROOM}`)).toEqual({ room: ROOM, key: null, incomplete: false });
    });

    it('a bad query room with no fragment room is not called incomplete: the page refuses it as it does today', () => {
        expect(readShareFragment('', '?room=not-a-uuid')).toEqual({ room: 'not-a-uuid', key: null, incomplete: false });
    });
});

describe('readShareFragment, a link with a key', () => {
    const incomplete = { room: null, key: null, incomplete: true };

    function keyed(hash: string, search = '') {
        const got = readShareFragment(hash, search);
        return { room: got.room, key: got.key && linkKeyText(got.key), incomplete: got.incomplete };
    }

    it('reads k first, the order every builder writes', () => {
        expect(keyed(`#k=${K}&room=${ROOM}`)).toEqual({ room: ROOM, key: K, incomplete: false });
        expect(keyed(`#k=${K}&room=${ROOM}`, '?s=nonce')).toEqual({ room: ROOM, key: K, incomplete: false });
    });

    it('takes the parameters in any order, and ignores one it does not know', () => {
        expect(keyed(`#room=${ROOM}&k=${K}`)).toEqual({ room: ROOM, key: K, incomplete: false });
        expect(keyed(`#x=1&k=${K}&y=2&room=${ROOM}`)).toEqual({ room: ROOM, key: K, incomplete: false });
    });

    it('keeps the case of the room id as written', () => {
        const upper = ROOM.toUpperCase();
        expect(keyed(`#k=${K}&room=${upper}`).room).toBe(upper);
    });

    it('decodes a percent escape the way Go url.ParseQuery does (link-shape rule: share fragments need no special case)', () => {
        expect(keyed(`#k=%41${K.slice(1)}&room=${ROOM}`)).toEqual({ room: ROOM, key: 'A' + K.slice(1), incomplete: false });
    });

    for (const [name, hash, search] of [
        ['a key with no room (a link cut at &)', `#k=${K}&`, ''],
        ['a key alone', `#k=${K}`, ''],
        ['a mail client escaped the &', `#k=${K}&amp;room=${ROOM}`, ''],
        ['an empty room', `#k=${K}&room=`, ''],
        ['a room that is not an id', `#k=${K}&room=not-a-uuid`, ''],
        ['a room id cut short', `#k=${K}&room=${ROOM.slice(0, 35)}`, ''],
        ['two rooms', `#k=${K}&room=${ROOM}&room=${OTHER_ROOM}`, ''],
        ['two keys', `#k=${K}&k=${K2}&room=${ROOM}`, ''],
        ['the same key twice', `#k=${K}&k=${K}&room=${ROOM}`, ''],
        ['an empty key', `#k=&room=${ROOM}`, ''],
        ['a key with no equals sign', `#k&room=${ROOM}`, ''],
        ['a malformed key', `#k=not-a-key&room=${ROOM}`, ''],
        ['a key one character short', `#k=${K.slice(1)}&room=${ROOM}`, ''],
        ['a key with padding', `#k=${K}==&room=${ROOM}`, ''],
        ['a key that is not canonical', `#k=${K.slice(0, 21)}B&room=${ROOM}`, ''],
        ['a room in the query only: never read when a key is held', `#k=${K}`, `?room=${ROOM}`],
        ['a key with an empty fragment room and a query room', `#k=${K}&room=`, `?room=${ROOM}`],
    ] as Array<[string, string, string]>) {
        it(`incomplete: ${name}`, () => expect(readShareFragment(hash, search)).toEqual(incomplete));
    }

    it('ignores a room in the query when the fragment names its own', () => {
        expect(keyed(`#k=${K}&room=${ROOM}`, `?room=${OTHER_ROOM}`).room).toBe(ROOM);
    });

    // The key is never taken from these, and neither is the room beside it, so the link
    // does not pass as a keyless one with its check gone (review 19, L1 and L2).
    for (const [name, hash, search] of [
        ['a k in the query', `#room=${ROOM}`, `?k=${K}`],
        ['a k and a room in the query', '', `?k=${K}&room=${ROOM}`],
        ['a room and a k in the query', '', `?room=${ROOM}&k=${K}`],
        ['K for k', `#K=${K}&room=${ROOM}`, ''],
        ['K for k, escaped', `#%4B=${K}&room=${ROOM}`, ''],
        ['a space in front', `# k=${K}&room=${ROOM}`, ''],
        ['a plus in front', `#+k=${K}&room=${ROOM}`, ''],
        ['a space behind', `#k%20=${K}&room=${ROOM}`, ''],
        ['a zero-width space in front', `#\u200Bk=${K}&room=${ROOM}`, ''],
        ['a byte order mark in front', `#\uFEFFk=${K}&room=${ROOM}`, ''],
        ['a bang in front', `#!k=${K}&room=${ROOM}`, ''],
        ['a slash in front', `#/k=${K}&room=${ROOM}`, ''],
        ['the name escaped with its equals sign', `#k%3D${K}&room=${ROOM}`, ''],
        ['the name escaped after the room', `#room=${ROOM}&k%3D${K}`, ''],
        ['a semicolon in front', `#;k=${K}&room=${ROOM}`, ''],
        ['a mail client\'s &amp; in front', `#room=${ROOM}&amp;k=${K}`, ''],
        ['the name escaped twice', `#%256B=${K}&room=${ROOM}`, ''],
        ['the fragment escaped whole', `#k%3D${K}%26room%3D${ROOM}`, ''],
    ] as Array<[string, string, string]>) {
        it(`incomplete: ${name}`, () => expect(readShareFragment(hash, search)).toEqual(incomplete));
    }

    it('takes a longer name for what it is: only k is a key', () => {
        expect(readShareFragment(`#kk=abc&room=${ROOM}`, '')).toEqual({ room: ROOM, key: null, incomplete: false });
        expect(readShareFragment(`#room=${ROOM}`, '?kk=1')).toEqual({ room: ROOM, key: null, incomplete: false });
    });
});

// The Go parser and this one over one file, cli/engine/code/testdata/link-shapes.json.
// A row where the two differ names its finding, which Go's TestLinkShapes requires, and
// no keyed row may have this reader join where Go refuses.
describe('link-shapes.json: what this reader makes of a pasted link', () => {
    const SHAPES = JSON.parse(
        readFileSync(new URL('../../cli/engine/code/testdata/link-shapes.json', import.meta.url), 'utf8'),
    ) as { rows: Array<{ name: string; kind: string; input: string; outcome: string; room?: string; key?: string; tsOutcome?: string; tsRoom?: string }> };
    const rows = SHAPES.rows.filter((row) => row.kind === 'share');

    it('holds the rows', () => expect(rows.length).toBeGreaterThan(50));

    for (const row of rows) {
        it(row.name, () => {
            const url = new URL(row.input);
            const got = readShareFragment(url.hash, url.search);
            const outcome = got.incomplete ? 'incomplete' : got.room ? 'ok' : 'none';
            const want = row.tsOutcome ?? row.outcome;
            expect(outcome).toBe(want);
            expect(got.key ? linkKeyText(got.key) : '').toBe(want === 'ok' ? row.key ?? '' : '');
            if (want === 'ok') expect(got.room).toBe(row.tsRoom ?? row.room);
        });
    }
});

describe('sameLinkKey', () => {
    it('compares what the keys are, not which object holds them', () => {
        expect(sameLinkKey(parseLinkKey(K), parseLinkKey(K))).toBe(true);
        expect(sameLinkKey(parseLinkKey(K), parseLinkKey(K2))).toBe(false);
    });

    it('reads no key as a value of its own: a keyed and a keyless link are different links', () => {
        expect(sameLinkKey(null, null)).toBe(true);
        expect(sameLinkKey(parseLinkKey(K), null)).toBe(false);
        expect(sameLinkKey(null, parseLinkKey(K))).toBe(false);
    });
});

// A fragment-only navigation does not reload the page by itself, so this is what
// decides whether a tab joined to one link is asked to read another. Compared on
// the room alone, a key that changed under the same room left the tab checking
// against the old key, and a fragment cut to nothing valid left it as it was.
describe('shareLinkChanged', () => {
    const held = { room: ROOM, key: parseLinkKey(K) };
    const now = (hash: string, search = '') => readShareFragment(hash, search);

    it('is false for the link the page holds, parameter order and unknown parameters aside', () => {
        expect(shareLinkChanged(now(`#k=${K}&room=${ROOM}`), held)).toBe(false);
        expect(shareLinkChanged(now(`#room=${ROOM}&k=${K}`), held)).toBe(false);
        expect(shareLinkChanged(now(`#k=${K}&room=${ROOM}&x=1`), held)).toBe(false);
    });

    it('is true for another room', () => {
        expect(shareLinkChanged(now(`#k=${K}&room=${OTHER_ROOM}`), held)).toBe(true);
        expect(shareLinkChanged(now(`#room=${OTHER_ROOM}`), { room: ROOM, key: null })).toBe(true);
    });

    it('is true for another key under the same room', () => {
        expect(shareLinkChanged(now(`#k=${K2}&room=${ROOM}`), held)).toBe(true);
    });

    it('is true when the key went or came, under the same room', () => {
        expect(shareLinkChanged(now(`#room=${ROOM}`), held)).toBe(true);
        expect(shareLinkChanged(now(`#k=${K}&room=${ROOM}`), { room: ROOM, key: null })).toBe(true);
    });

    it('is true when the link became incomplete, which a room comparison reads as no change', () => {
        for (const cut of [`#k=${K}`, `#k=${K}&`, `#k=bad&room=${ROOM}`, '#room=', '#room=junk', `#k=${K}&amp;room=${ROOM}`]) {
            expect(shareLinkChanged(now(cut), held), cut).toBe(true);
        }
    });

    it('is false when the fragment no longer names a link at all, as it always was', () => {
        // The tab keeps its transfer: nothing in the address asks for another one.
        expect(shareLinkChanged(now(''), held)).toBe(false);
        expect(shareLinkChanged(now('#about'), held)).toBe(false);
    });

    it('is true on a page that holds no link when a whole one arrives, and false when none does', () => {
        const none = { room: null, key: null };
        expect(shareLinkChanged(now(`#k=${K}&room=${ROOM}`), none)).toBe(true);
        expect(shareLinkChanged(now(`#room=${ROOM}`), none)).toBe(true);
        expect(shareLinkChanged(now(''), none)).toBe(false);
    });

    it('still reads a legacy ?room= address the way the page joined it', () => {
        expect(shareLinkChanged(now('', `?room=${ROOM}`), { room: ROOM, key: null })).toBe(false);
        expect(shareLinkChanged(now('', `?room=${OTHER_ROOM}`), { room: ROOM, key: null })).toBe(true);
    });
});
